package com.bank.bonus.service;

import com.bank.bonus.model.Employee;
import com.bank.bonus.repository.EmployeeRepository;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class BonusService {
    private static final Logger log = Logger.getLogger(BonusService.class.getName());
    private final EmployeeRepository repo;
    public BonusService(EmployeeRepository repo) { this.repo = repo; }

    private BigDecimal average(List<Employee> all) {
        BigDecimal sum = all.stream().map(Employee::getSalary).reduce(BigDecimal.ZERO, BigDecimal::add);
        return sum.divide(BigDecimal.valueOf(all.size()), 2, RoundingMode.HALF_UP);
    }

    // WHERE salary > AVG  ORDER BY salary DESC  LIMIT 5
    public List<Employee> topFiveByLimit() {
        List<Employee> all = repo.findAll();
        BigDecimal avg = average(all);
        return all.stream()
                .filter(e -> e.getSalary().compareTo(avg) > 0)
                .sorted((a, b) -> b.getSalary().compareTo(a.getSalary()))
                .limit(5)                                  // arbitrary on ties
                .collect(Collectors.toList());
    }

    // RANK() OVER (ORDER BY salary DESC) <= 5  → keeps ALL ties at the boundary
    public List<Employee> topFiveByRank() {
        List<Employee> all = repo.findAll();
        BigDecimal avg = average(all);
        List<Employee> above = all.stream()
                .filter(e -> e.getSalary().compareTo(avg) > 0)
                .sorted((a, b) -> b.getSalary().compareTo(a.getSalary()))
                .collect(Collectors.toList());
        List<Employee> result = new ArrayList<>();
        int rank = 0, position = 0;
        BigDecimal prev = null;
        for (Employee e : above) {
            position++;
            if (prev == null || e.getSalary().compareTo(prev) != 0) rank = position; // RANK skips
            if (rank > 5) break;
            result.add(e);
            prev = e.getSalary();
        }
        log.info(() -> "avg=" + avg + ", rank-based winners=" + result.size());
        return result;
    }
}
