package com.bank.bonus;

import com.bank.bonus.model.Employee;
import com.bank.bonus.repository.EmployeeRepository;
import com.bank.bonus.service.BonusService;

public class BonusApplication {
    public static void main(String[] args) {
        BonusService svc = new BonusService(new EmployeeRepository());
        System.out.println("LIMIT 5 version:");
        for (Employee e : svc.topFiveByLimit()) System.out.printf("  %-14s Rs.%s%n", e.getName(), e.getSalary());
        System.out.println("RANK <= 5 version (fair on ties):");
        for (Employee e : svc.topFiveByRank()) System.out.printf("  %-14s Rs.%s%n", e.getName(), e.getSalary());
    }
}
